export function sampleState() {
  const now=Date.now(), ago=h=>new Date(now-h*3600000).toISOString();
  const rows=[
    ['m1','Ada from Mail Wizard','hello@example.com','A little more room to think.',0.2,'Welcome to Mail Wizard.\n\nYour inbox should feel like a desk you enjoy sitting down at. A few thoughtful tools, a little breathing room, and everything in its place.\n\nThis is a sample inbox. The people and messages here are fictional, so you can explore freely. Nothing you do here sends real email.\n\nWhen you are ready, connect a compatible mail account from Settings. Your messages go directly between your device and your provider. There is no Mail Wizard mail server in the middle.\n\nA few things to try:\n• Press C to start a letter.\n• Star something worth coming back to.\n• Search with from:, is:unread, or has:attachment.\n• Switch to Focus to see only unread messages.\n\nHere is to a quieter inbox.\n\nAda\nMail Wizard',true,'Personal',false],
    ['m2','Nora Williams','nora@example.com','The first chapter is yours.',1.2,'Hi there,\n\nI have been thinking about what we said yesterday. The best ideas are usually the ones that give us space to do our own thing.\n\nI put together a few notes for our next chapter. Nothing polished, just a starting point. I would love your thoughts before Friday.\n\nThree things I keep coming back to:\n\n01  Make it useful before making it bigger.\n02  Leave a little room for the unexpected.\n03  Build something we would want to use ourselves.\n\nDoes Thursday afternoon work for a quick catch-up?\n\nSpeak soon,\nNora',false,'Work',true],
    ['m3','The Reading Room','letters@example.com','A short list for a long weekend',2.4,'This week, a handful of things worth your attention.\n\nAn essay about keeping a notebook. A walk without a destination. And a reminder that your best ideas do not always arrive at your desk.\n\nNo links to chase today. Just a good excuse to close your inbox for a while.\n\nThe Reading Room',false,'Reading',false],
    ['m4','Oliver Chen','oliver@example.com','Re: A small update',3.5,'That sounds good to me. Let us keep the simpler version and see how it feels after a week.\n\nThanks for taking the time to think it through.\n\nOliver',true,'Work',false],
    ['m5','Maya Patel','maya@example.com','Coffee, and a very good idea',4.8,'Found a little place near the station that I think you would like. Good coffee, big windows, no rush.\n\nSaturday morning? I have a slightly ridiculous idea I want to run past you.\n\nMaya',false,'Personal',true],
    ['m6','Field Notes','journal@example.com','Issue 018 / Start where you are',7,'A monthly letter on making things with care.\n\nThis month: the first draft, the long walk, and the overlooked pleasure of finishing one small thing.\n\nTake what you need. Leave the rest.\n\nField Notes',true,'Reading',false],
    ['m7','Sam Rivera','sam@example.com','Everything is ready for Monday',23,'The final notes are ready. I have double-checked the dates and added the small changes we discussed.\n\nWe are in a good place. Have a lovely weekend.\n\nSam',true,'Work',false],
    ['m8','Lena Brooks','lena@example.com','The photos from our walk',25,'A few favourites from Sunday. The light was doing something wonderful by the water.\n\nI will send the full set once I have sorted through them.\n\nLena',true,'Personal',false],
    ['m9','Studio Sunday','studio@example.com','A place for things that matter',28,'Our studio notebook is open.\n\nThis week we have been sketching, revisiting old ideas, and asking what we can leave out.\n\nThe answer, almost always, is more than we think.\n\nUntil next Sunday.',true,'Reading',false],
    ['m10','Nora Williams','nora@example.com','One more thought for the notebook',47,'A quick thought before I forget: let us leave the last page blank. There is always something we have not thought of yet.\n\nNora',true,'Work',true],
    ['m11','You','you@example.com','Re: Next week',49,'Thursday works for me. Looking forward to it!',true,'Personal',false,'sent'],
    ['m12','You','you@example.com','A note for later',0.5,'I wanted to share a thought about the project... ',true,'Work',false,'drafts'],
    ['m13','Jonas Müller','jonas@example.com','Thank you for the thoughtful feedback',72,'All the changes are in. Thank you for being so specific about what could be clearer. It made the next draft much easier.\n\nBest,\nJonas',true,'Work',false,'archive'],
    ['m14','The Reading Room','letters@example.com','Saved for a rainy afternoon',80,'A few things for another day.\n\nThere is no rush.\n\nThe Reading Room',true,'Reading',false,'archive']
  ];
  return {schema:1,mode:'demo',account:{name:'Your space',email:'you@example.com'},messages:rows.map(([id,name,email,subject,h,body,read,label,starred,folder])=>({id,threadId:id,from:{name,email},to:[{name:'You',email:'you@example.com'}],cc:[],subject,date:ago(h),body,read,labels:[label],starred,localDraft:folder==='drafts',folder:folder || 'inbox',attachments:id==='m2'?[{name:'Chapter-one.txt',type:'text/plain',size:146,data:btoa('Make it useful before making it bigger.\nLeave a little room for the unexpected.\nBuild something we would want to use ourselves.')}]:[]})),settings:{signature:'',undoSeconds:8},contacts:[]};
}
